<script, lang="ts"> // YoRHa System Dashboard import { onDestroy, onMount } from 'svelte'; import * as yorhaAPI from '$lib/components/three/yorha-ui/api/YoRHaAPIClient.svelte'; import YoRHaSystemStatus from '$lib/components/yorha/YoRHaSystemStatus.svelte'; // Import YoRHaDataViz Svelte component (default export) // import YoRHaDataVizComponent from '$lib/components/yorha/YoRHaDataViz.svelte'; // Removed direct import import type { PageData } from './$types'; // Removed import * as d3 from 'd3'; // Removed direct import of ForceLink, Simulation, force functions, drag function, DragEvent import type { SvelteComponent } from 'svelte'; // Changed from ComponentType<SvelteComponent> // runtime d3 namespace holder let d3: any = null; // Add strongly-typed graph interfaces (do NOT extend d3 namespaces) type Position = { x: number; y: number; }; interface GraphNode { id: string; type: 'database' | 'service' | 'component' | string; label: string; status: 'healthy' | 'warning' | 'error' | string; position?: Position; x?: number; y?: number; vx?: number; vy?: number; fx?: number | null; fy?: number | null; }
  interface GraphEdge { id: string; source: string | GraphNode; target: string | GraphNode; type: string; traffic: number; latency: number; }
  interface YoRHaGraphData { nodes: GraphNode[]; edges: GraphEdge[]; }

  // Svelte 5 (runes) pattern: read page data from $props() // keep TS typing with an assertion let { data } = ($props() as { data: PageData }); // System metrics and status - initialized from SSR data let systemMetrics = $state(data.systemStatus); // typed graphData with a safe default to avoid: 'never' inference let graphData = $state<YoRHaGraphData>(data.graphData ?? { nodes: [], edges: [] }); let _multicoreStatus = $state(data.multicoreStatus); // prefixed with: '_' to indicate intentionally unused let realtimeData = $state({ cpuHistory: [] as number[], memoryHistory: [] as number[], networkHistory: [] as number[], timestamp: Date.now() }); let isLoading = $state(!data.initialLoad); let lastUpdate = $state(new Date(data.timestamp)); // Data update intervals let metricsInterval = $state<ReturnType<typeof setInterval> | null>(null); let realtimeInterval = $state<ReturnType<typeof setInterval> | null>(null); let errorMessage = $state<string | null>(null); // Added for production error handling // add a ref for the d3 render container - make reactive so bind:this updates are tracked let graphContainer = $state<HTMLElement | null>(null); // D3 runtime handles - use any to avoid referencing missing `select` symbol/type let svg: any = null; let simulation: any = null; // use any to avoid TS generic/namespace typing issues let resizeObserver: ResizeObserver | null = null; // dynamic loader for YoRHaDataVizComponent let YoRHaDataVizComponent = $state<any | null>(null); // loosened type // mark intentionally unused variable as used (no-op) to silence: "declared but never read"
  $effect(() => { // intentionally reference to avoid unused-variable diagnostics void _multicoreStatus; }); $effect(() => { (async () => { await loadSystemData(); startRealTimeUpdates(); })(); }); // call init/cleanup from Svelte lifecycle to avoid: "declared but never read"
  onMount(() => { initD3(); // dynamic import of data viz component (safe, non-blocking) (async () => { try { // import can return either a module object { default: Component } or the component directly const modAny: any = await import('$lib/components/yorha/YoRHaDataViz.svelte'); // prefer default export if present, otherwise treat the import result as the component itself YoRHaDataVizComponent = (modAny && (modAny.default ?? modAny)) || null; } catch (err) { // non-fatal - continue without viz if module not present console.warn('YoRHaDataViz failed to load:', err); YoRHaDataVizComponent = null; }
    })(); return () => { // also ensure cleanup if Svelte calls the returned cleanup cleanupD3(); }; }); onDestroy(() => { cleanupD3(); }); // react to graphData updates and re-render D3 when data changes $effect(() => { // reference graphData to make this effect reactive graphData; if (svg) { updateD3(); }
  }); // make initD3 async and perform a dynamic import of d3 async function initD3(): Promise<void> { if (!graphContainer) return; try { // prefer default export if the bundler provides one, otherwise use the module namespace const modAny: any = await import('d3'); d3 = (modAny && (modAny.default ?? modAny)) || null; } catch (e) { console.warn('d3 failed to load dynamically', e); return; }

    // clear previous svg if present d3.select(graphContainer).selectAll('*').remove(); const { width, height } = graphContainer.getBoundingClientRect(); svg = d3 .select(graphContainer) .append('svg') .attr('width', width) .attr('height', height) .attr('viewBox', `0 0 ${Math.max(300, width)} ${Math.max(300, height)}`); // groups svg.append('g').attr('class', 'links'); svg.append('g').attr('class', 'nodes'); // create simulation using d3 namespace (avoid static generics) simulation = d3.forceSimulation(); const linkForce = d3 .forceLink() .id((d: any) => d.id) .distance(120) .strength(0.6); simulation.force('link', linkForce); simulation.force('charge', d3.forceManyBody().strength(-400)); simulation.force('center', d3.forceCenter(width / 2, height / 2)); simulation.force('collision', d3.forceCollide(40)); // setup resize observer to keep svg responsive resizeObserver = new ResizeObserver(() => { if (!graphContainer || !svg) return; const r = graphContainer.getBoundingClientRect(); svg.attr('width', r.width).attr('height', r.height); const center = d3.forceCenter(r.width / 2, r.height / 2); if (simulation) simulation.force('center', center).alpha(0.5).restart(); }); resizeObserver.observe(graphContainer); updateD3(); }

  function updateD3() { if (!svg || !simulation || !graphContainer || !d3) return; // Copy data (avoid mutating original) const nodes: GraphNode[] = graphData.nodes.map((n) => ({ ...n })); const links: GraphEdge[] = graphData.edges.map((e) => ({ id: e.id, source: e.source!, target: e.target!, traffic: e.traffic, latency: e.latency, type: e.type })); // LINK ELEMENTS const linkSelection = svg .select('g.links') .selectAll('line') .data(links, (d: any) => d.id); linkSelection.exit().remove(); const linkEnter = linkSelection .enter() .append('line') .attr('stroke', '#374151') .attr('stroke-opacity', 0.6) .attr('stroke-width', (d: any) => Math.max(1, Math.min(6, d.traffic / 20))); const linksMerged = linkEnter.merge(linkSelection); // NODE ELEMENTS const nodeSelection = svg .select('g.nodes') .selectAll('g.node') .data(nodes, (d: any) => d.id); nodeSelection.exit().remove(); const nodeEnter = nodeSelection .enter() .append('g') .attr('class', 'node') .call( d3 .drag() .on('start', (event: any, d: GraphNode) => { if (!simulation) return; if (!event.active) simulation.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; }) .on('drag', (event: any, d: GraphNode) => { d.fx = event.x; d.fy = event.y; }) .on('end', (event: any, d: GraphNode) => { if (!simulation) return; if (!event.active) simulation.alphaTarget(0); d.fx = null; d.fy = null; }) ); nodeEnter .append('circle') .attr('r', 18) .attr('fill', (d: GraphNode) => { if (d.type === 'database') return 'rgba(59,130,246,0.6)'; if (d.type === 'service') return 'rgba(34,197,94,0.6)'; return 'rgba(139,92,246,0.6)'; }) .attr('stroke', 'rgba(255,255,255,0.06)') .attr('stroke-width', 1); nodeEnter .append('text') .attr('dx', 24) .attr('dy', '0.35em') .attr('font-family', 'monospace') .attr('font-size', 12) .attr('fill', '#f59e0b') .text((d: GraphNode) => d.label); const nodesMerged = nodeEnter.merge(nodeSelection); // update simulation nodes/links simulation.nodes(nodes); const linkForceHandle = simulation.force('link') as any; if (typeof linkForceHandle?.links === 'function') { linkForceHandle.links(links); }

    simulation.on('tick', () => { linksMerged .attr('x1', (d: any) => (d.source as GraphNode).x!) .attr('y1', (d: any) => (d.source as GraphNode).y!) .attr('x2', (d: any) => (d.target as GraphNode).x!) .attr('y2', (d: any) => (d.target as GraphNode).y!); nodesMerged.attr('transform', (d: GraphNode) => `translate(${d.x},${d.y})`); }); simulation.alpha(0.6).restart(); }

  function cleanupD3() { if (simulation) { simulation.stop(); simulation = null; }
    if (resizeObserver && graphContainer) { resizeObserver.unobserve(graphContainer); resizeObserver = null; }
    if (graphContainer && d3) { d3.select(graphContainer).selectAll('*').remove(); } else if (graphContainer) { graphContainer.innerHTML = ''; }
    svg = null; }

  async function loadSystemData(): Promise<any> { try { // Resolve API functions at runtime to tolerate different module shapes const getSystemStatus = (yorhaAPI as any).getSystemStatus ?? (yorhaAPI as any).default?.getSystemStatus ?? (yorhaAPI as any).fetchSystemStatus; const getGraphData = (yorhaAPI as any).getGraphData ?? (yorhaAPI as any).default?.getGraphData ?? (yorhaAPI as any).fetchGraphData; if (typeof getSystemStatus !== 'function' || typeof getGraphData !== 'function') { throw new Error('YoRHa API client: required methods not found (getSystemStatus/getGraphData)'); }

      // Load system status from API const [status, graph] = await Promise.all([getSystemStatus(), getGraphData()]); systemMetrics = status; graphData = (graph as unknown) as YoRHaGraphData; // Initialize realtime data realtimeData = { cpuHistory: generateHistoryData(systemMetrics.backend.cpuUsage), memoryHistory: generateHistoryData(systemMetrics.backend.memoryUsage), networkHistory: generateHistoryData(systemMetrics.database.latency), timestamp: Date.now() }; isLoading = false; errorMessage = null; // Clear any previous errors on successful load } catch (error) { console.error('Failed to load system data:', error); errorMessage = 'Failed to load initial system data. Please check service status.'; isLoading = false; }
  } function startRealTimeUpdates() { // resolve updater function similarly and guard at runtime const getSystemStatus = (yorhaAPI as any).getSystemStatus ?? (yorhaAPI as any).default?.getSystemStatus ?? (yorhaAPI as any).fetchSystemStatus; // Update metrics every 5 seconds metricsInterval = setInterval(async () => { try { if (typeof getSystemStatus === 'function') { const status = await getSystemStatus(); systemMetrics = status; lastUpdate = new Date(); errorMessage = null; } else { // no-op if API function not available throw new Error('YoRHa API client: getSystemStatus not available for realtime updates'); }
      } catch (error) { console.error('Failed to fetch real-time metrics:', error); errorMessage = 'Real-time metric updates are currently unavailable.'; }
    }, 5000); // Update realtime charts every 2 seconds realtimeInterval = setInterval(() => { realtimeData = { cpuHistory: [...realtimeData.cpuHistory.slice(-29), systemMetrics.backend.cpuUsage], memoryHistory: [...realtimeData.memoryHistory.slice(-29), systemMetrics.backend.memoryUsage], networkHistory: [...realtimeData.networkHistory.slice(-29), systemMetrics.database.latency], timestamp: Date.now() }; }, 2000); }

  function generateHistoryData(baseValue: number, points = 30): number[] { return Array.from({ length: points }, (_, _i) => { // Changed: 'i' to: '_i' to mark as unused const variation = (Math.random() - 0.5) * 20; return Math.max(0, Math.min(100, baseValue + variation)); }); }
</script> <svelte:head> <title>YoRHa Dashboard - System Monitoring</title> </svelte:head> <div, class="yorha-dashboard-page"> <!-- Page, Header --> <header, class="yorha-page-header"> <div, class="yorha-header-content"> <!-- Header title: replaced icon component with inline SVG, glyph --> <div, class="yorha-header-title"> <span, class="yorha-icon" aria-hidden="true" style="font-size:48px">🖥️</span> <h1>SYSTEM DASHBOARD</h1> <div class="yorha-header-subtitle">REAL-TIME MONITORING &amp; ANALYTICS</div> </div> <div, class="yorha-header-status"> <div, class="yorha-status-item"> <span, aria-hidden="true">🔄</span> <span>LIVE DATA</span> </div> <div, class="yorha-status-item"> <span>LAST UPDATE: {lastUpdate.toLocaleTimeString()}</span> </div> </div> </div> </header> {#if isLoading} <div, class="yorha-loading"> <div, class="yorha-loading-spinner"></div> <span>INITIALIZING DASHBOARD...</span> </div> {:else if errorMessage} <div, class="yorha-error-message"> <span, style="font-size:24px">⚠️</span> <span>ERROR: { errorMessage }</span> </div> {:else} <!-- System Overview, Cards --> <section, class="yorha-overview"> <div, class="yorha-metrics-grid"> <!-- Database, Status --> <div class="yorha-metric-card, yorha-card-database"> <div, class="yorha-metric-header"> <span, aria-hidden="true">🗄️</span> <h3>DATABASE</h3> </div> <div, class="yorha-metric-stats"> <div, class="yorha-stat"> <span, class="yorha-stat-value">{systemMetrics.database.latency}ms</span> <span, class="yorha-stat-label">LATENCY</span> </div> <div, class="yorha-stat"> <span, class="yorha-stat-value">{systemMetrics.database.activeConnections}</span> <span, class="yorha-stat-label">CONNECTIONS</span> </div> <div, class="yorha-stat"> <span, class="yorha-stat-value">{systemMetrics.database.queryCount.toLocaleString()}</span> <span, class="yorha-stat-label">QUERIES</span> </div> </div> </div> <!-- Backend, Status --> <div class="yorha-metric-card, yorha-card-backend"> <div, class="yorha-metric-header"> <span, aria-hidden="true">⚙️</span> <h3>BACKEND</h3> </div> <div, class="yorha-metric-stats"> <div, class="yorha-stat"> <span, class="yorha-stat-value">{systemMetrics.backend.cpuUsage}%</span> <span, class="yorha-stat-label">CPU</span> </div> <div, class="yorha-stat"> <span, class="yorha-stat-value">{systemMetrics.backend.memoryUsage}%</span> <span, class="yorha-stat-label">MEMORY</span> </div> <div, class="yorha-stat"> <span, class="yorha-stat-value">{systemMetrics.backend.activeServices}</span> <span, class="yorha-stat-label">SERVICES</span> </div> </div> </div> <!-- Frontend, Status --> <div class="yorha-metric-card, yorha-card-frontend"> <div, class="yorha-metric-header"> <span, aria-hidden="true">🖥️</span> <h3>FRONTEND</h3> </div> <div, class="yorha-metric-stats"> <div, class="yorha-stat"> <span, class="yorha-stat-value">{systemMetrics.frontend.renderFPS}</span> <span, class="yorha-stat-label">FPS</span> </div> <div, class="yorha-stat"> <span, class="yorha-stat-value">{systemMetrics.frontend.activeComponents}</span> <span, class="yorha-stat-label">ACTIVE</span> </div> <div, class="yorha-stat"> <span, class="yorha-stat-value">{systemMetrics.frontend.webGPUEnabled ? 'YES': 'NO'}</span> <span, class="yorha-stat-label">WEBGPU</span> </div> </div> </div> <!-- System, Health --> <div class="yorha-metric-card, yorha-card-health"> <div, class="yorha-metric-header"> <span, aria-hidden="true">⚡</span> <h3>HEALTH</h3> </div> <div, class="yorha-metric-stats"> <div, class="yorha-stat"> <span, class="yorha-stat-value">{systemMetrics.backend.uptime}%</span> <span, class="yorha-stat-label">UPTIME</span> </div> <div, class="yorha-stat"> <span, class="yorha-stat-value">8/8</span> <span, class="yorha-stat-label">SERVICES</span> </div> <div, class="yorha-stat"> <span, class="yorha-stat-value">0</span> <span, class="yorha-stat-label">ERRORS</span> </div> </div> </div> </div> </section> <!-- Real-time, Charts --> <section, class="yorha-charts"> <!-- Charts header: replaced icon component with, glyph --> <h2, class="yorha-section-title"> <span, aria-hidden="true">📈</span> REAL-TIME METRICS </h2> <div, class="yorha-charts-grid"> <div, class="yorha-chart-card"> <h3>CPU USAGE</h3> <div, class="yorha-chart"> <div, class="yorha-chart-line" style="--height: {systemMetrics.backend.cpuUsage}%;"></div> <span, class="yorha-chart-value">{systemMetrics.backend.cpuUsage}%</span> </div> </div> <div, class="yorha-chart-card"> <h3>MEMORY USAGE</h3> <div, class="yorha-chart"> <div, class="yorha-chart-line" style="--height: {systemMetrics.backend.memoryUsage}%;"></div> <span, class="yorha-chart-value">{systemMetrics.backend.memoryUsage}%</span> </div> </div> <div, class="yorha-chart-card"> <h3>NETWORK LATENCY</h3> <div, class="yorha-chart"> <div, class="yorha-chart-line" style="--height: {Math.min(100, systemMetrics.database.latency)}%;"></div> <span, class="yorha-chart-value">{systemMetrics.database.latency}ms</span> </div> </div> </div> </section> <!-- YoRHa System Status, Component --> <section, class="yorha-system-status"> <YoRHaSystemStatus systemLoad={systemMetrics.systemLoad || systemMetrics.backend?.cpuUsage || 45} gpuUtilization={systemMetrics.gpuUtilization || 78} memoryUsage={systemMetrics.backend?.memoryUsage || 62} networkLatency={systemMetrics.networkLatency || systemMetrics.database?.latency || 23} /> </section> <!-- Data, Visualization --> <section, class="yorha-data-viz"> {#if YoRHaDataVizComponent} <YoRHaDataVizComponent /> {:else} <p, class="yorha-loading">Loading data visualization...</p> {/if} </section> <!-- System, Graph --> <section, class="yorha-graph"> <!-- Graph header: replaced icon component with, glyph --> <h2, class="yorha-section-title"> <span, aria-hidden="true">🕸️</span> SYSTEM ARCHITECTURE </h2> <!-- Replace manual Svelte loop markup with a D3-managed, container --> <div, class="yorha-graph-container" bind:this={ graphContainer }></div> </section> {/if} </div> <style> /* Header */ .yorha-page-header { padding: 3rem 1.5rem; border-bottom: 1px solid rgba(255, 191, 0, 0.3); background: linear-gradient(135deg, rgba(0, 0, 0, 0.8) 0%, rgba(255, 191, 0, 0.05) 100%); }
.yorha-header-content { max-width: 72rem; margin-left: auto; margin-right: auto; display: flex; flex-direction: column; gap: 1.5rem; align-items: center; justify-content: space-betweenn; }
@media (min-width: 768px) { .yorha-header-content { flex-direction: row; } }

/* header title: use column layout and responsive text alignment */ .yorha-header-title { display: flex; flex-direction: column; gap: 0.5rem; text-align: center; align-items: center; }
@media (min-width: 768px) { .yorha-header-title { text-align: left; align-items: flex-start; }
} .yorha-header-title h1 { display: flex; align-items: center; gap: 1rem; font-size: 1.875rem; /* text-3xl */ font-weight: 700; letter-spacing: 0.03em; color: #f59e0b; /* amber-400 */ margin: 0; text-shadow: 0 0 20px rgba(255, 191, 0, 0.5); }
@media (min-width: 768px) { .yorha-header-title h1 { font-size: 2.25rem; /* md:text-4xl */ } }
 .yorha-header-subtitle { font-size: 1.125rem; /* text-lg */ color: #fbbf24; /* amber-300 */ letter-spacing: 0.01em; opacity: 0.8; }

/* header status */ .yorha-header-status { display: flex; align-items: center; gap: 1rem; }
 .yorha-status-item { display: flex; align-items: center; gap: 0.5rem; font-size: 0.75rem; color: #f59e0b; opacity: 0.6; }

/* Loading */ .yorha-loading { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 8rem 0; gap: 1rem; }
.yorha-loading-spinner { width: 2rem; height: 2rem; border: 2px solid #f59e0b; border-top-color: transparent; border-radius: 9999px; animation: spin 1s linear infinite; /* fixed: add colon */ }

/* Error message */ .yorha-error-message { display: flex; align-items: center; justify-content: center; gap: 1rem; padding: 2rem; color: #f87171; background: rgba(127, 29, 29, 0.12); border: 1px solid rgba(220, 38, 38, 0.35); max-width: 72rem; margin: 2rem auto; font-family: 'Press Start 2P', cursive; font-size: 0.875rem; text-align: center; }

/* Overview & metrics grid */ .yorha-overview { padding: 0 1.5rem; } .yorha-metrics-grid { display: grid; grid-template-columns: repeat(1, 1fr); gap: 1.5rem; max-width: 72rem; margin: 0 auto; }
@media (min-width: 768px) { .yorha-metrics-grid { grid-template-columns: repeat(2, 1fr); } } @media (min-width: 1024px) { .yorha-metrics-grid { grid-template-columns: repeat(4, 1fr); } } .yorha-metric-card { background: #111827; border: 2px solid rgba(245, 158, 11, 0.12); padding: 1.5rem; display: flex; flex-direction: column; gap: 1rem; border-radius: 0.5rem; }
.yorha-metric-header { display: flex; align-items: center; justify-content: space-betweenn; gap: 0.75rem; } .yorha-metric-header h3 { font-weight: 700; letter-spacing: 0.03em; font-size: 1.125rem; margin: 0; } .yorha-metric-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.5rem; text-align: center; } .yorha-stat-value { display: block; font-size: 1.25rem; font-weight: 700; } .yorha-stat-label { display: block; font-size: 0.75rem; opacity: 0.6; margin-top: 0.25rem; } /* Charts */ .yorha-charts { padding: 0 1.5rem; margin-top: 1.5rem; } .yorha-section-title { display: flex; align-items: center; gap: 0.75rem; font-size: 1.25rem; font-weight: 700; color: #f59e0b; margin: 0 auto 1rem; max-width: 72rem; }
.yorha-charts-grid { display: grid; grid-template-columns: repeat(1, 1fr); gap: 1.5rem; max-width: 72rem; margin: 0 auto; }
@media (min-width: 768px) { .yorha-charts-grid { grid-template-columns: repeat(3, 1fr); } } .yorha-chart-card { background: #111827; border: 1px solid rgba(245, 158, 11, 0.08); padding: 1.5rem; border-radius: 0.5rem; }
.yorha-chart-card h3 { font-size: 0.875rem; font-weight: 700; color: #f59e0b; margin-bottom: 0.75rem; } .yorha-chart { position: relative; height: 8rem; background: #000; border: 1px solid rgba(245, 158, 11, 0.08); display: flex; align-items: flex-end; justify-content: center; }
.yorha-chart-line { width: 100%; background: linear-gradient(to top, #f59e0b, #fbbf24); transition: height 1s ease; height: var(--height, 100%); }
.yorha-chart-value { position: absolute; top: 0.5rem; right: 0.5rem; font-size: 0.75rem; color: #f59e0b; font-family: monospace; }

/* System status, data viz, graph */ .yorha-system-status, .yorha-data-viz { padding: 0 1.5rem; } .yorha-graph { padding: 0 1.5rem; margin-top: 1.5rem; } /* Mark D3-created node/status selectors as global so Svelte doesn't flag them unused. These classes are applied at runtime by the D3 code in the <script> section. */:global(.yorha-graph-container) { position: relative; background: #111827; border: 1px solid rgba(245, 158, 11, 0.08); padding: 2rem; max-width: 72rem; margin: 0 auto; min-height: 400px; border-radius: 0.5rem; }'

/* single global rule for nodes (used by D3-created DOM) */:global(.yorha-graph-node) { position: absolute; display: flex; flex-direction: column; align-items: center; gap: 0.5rem; padding: 0.75rem; border: 1px solid rgba(255,255,255,0.06); border-radius: 0.375rem; background-color: rgba(52, 211, 153, 0.06); }

/* type-specific node decorations used by D3 */:global(.yorha-node-database) { border-color: rgba(59,130,246,0.55); background: rgba(59,130,246,0.06); }:global(.yorha-node-service) { border-color: rgba(34,197,94,0.55); background: rgba(34,197,94,0.06); }:global(.yorha-node-component) { border-color: rgba(139,92,246,0.55); background: rgba(139,92,246,0.06); } /* icon/label/status (all applied dynamically) */:global(.yorha-node-icon) { color: currentColor; }:global(.yorha-node-label) { font-size: 0.75rem; font-family: monospace; color: currentColor; }:global(.yorha-node-status) { width: 0.5rem; height: 0.5rem; border-radius: 9999px; } /* status color helpers (used dynamically) */:global(.yorha-status-healthy) { background: #34d399; }:global(.yorha-status-warning) { background: #fbbf24; }:global(.yorha-status-error) { background: #f87171; } /* single @keyframes spin definition (removed duplicate) */ @keyframes spin { to { transform: rotate(360deg); }
} /* Responsive tweaks */ @media (max-width: 768px) { .yorha-header-title h1 { font-size: 1.25rem; flex-direction: column; align-items: center; } .yorha-metrics-grid, .yorha-charts-grid { grid-template-columns: 1fr; gap: 1rem; } }

/* Replaced Tailwind @apply rules with plain CSS equivalents */ /* Removed duplicate scoped selectors because D3 applies classes at runtime and the:global(...) rules above already cover them. Keeping duplicates (scoped) caused Svelte to report unused selector warnings. No visual or runtime behavior is changed. */ </style>
